import React from 'react';

import { selectHikingScheduleItemInModal } from '@apps/Hiking/@components/ScheduleSelectModal';
import { IHikingGpx } from '@apps/Hiking/@types/hiking.types';
import PohButton from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

const HikingTrackEditModal = ({
  id_hiking,
  hikingTrack,
  onSave,
}: {
  id_hiking: number;
  onSave: (up: IHikingGpx) => void;
  hikingTrack: IHikingGpx;
}) => {
  const [data, setData] = React.useState({
    name: hikingTrack.name,
    id_hiking_schedule: hikingTrack.id_hiking_schedule,
    schedule: hikingTrack.schedule,
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...hikingTrack,
      ...data,
    });
  };
  return (
    <form onSubmit={handleSubmit} className="d-flex flex-column" style={{ minWidth: 400, gap: 12 }}>
      <PohInput
        value={data.name}
        onChange={(v) => setData((cur) => ({ ...cur, name: v }))}
        name="name"
        label="Название"
        message={
          <small className="text-muted">
            Отличное название это точки маршрута разделенные символом —{' '}
          </small>
        }
      />
      <PohRow>
        <PohCol sm={10}>
          <PohInput
            label="Связь с планом похода"
            placeholder="Нажмите чтобы выбрать пункт плана"
            value={data.schedule ? data.schedule?.name : ''}
            readOnly
            onClick={async () => {
              const selected = await selectHikingScheduleItemInModal(id_hiking);
              setData((cur) => ({
                ...cur,
                id_hiking_schedule: selected ? selected.id : null,
                schedule: selected ? selected : null,
              }));
            }}
          />
        </PohCol>
        <PohCol sm={2}>
          <PohButton
            className="mt-3"
            icon={IconsEnum.close}
            onClick={() =>
              setData((cur) => ({
                ...cur,
                id_hiking_schedule: null,
                schedule: null,
              }))
            }
          />
        </PohCol>
      </PohRow>

      <footer className="text-end mt-3">
        <PohButton type="submit">Сохранить</PohButton>
      </footer>
    </form>
  );
};

export const editHikingTrackAsync = (
  id_hiking: number,
  hikingTrack: IHikingGpx,
): Promise<IHikingGpx> => {
  return new Promise((res) => {
    showModal({
      children: (clos) => (
        <HikingTrackEditModal
          id_hiking={id_hiking}
          hikingTrack={hikingTrack}
          onSave={(up) => {
            res(up);
            clos();
          }}
        />
      ),
    });
  });
};
